declarations.code:
abbrev ExactBodyMap (S : Set E) (K : Set F) (H : Submodule ℝ F) :=
  {A : E →L[ℝ] F // Function.Injective A ∧ LinearMap.range A.toLinearMap = H ∧
    A '' S = K ∩ (H : Set F)}

